var minMoves2 = function(nums) {
    nums.sort((a, b) => a - b);

    const mid = nums.length & 1 ?
        nums[(nums.length - 1) / 2] :
        Math.floor((nums[(nums.length / 2) - 1] + nums[nums.length / 2]) / 2);

    let res = 0;

    for (const num of nums) {
        res += Math.abs(num - mid);
    }

    return res;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minMoves2 = function(nums) {
    nums.sort((a, b) => a - b);

    const halfLen = Math.floor(nums.length / 2);
    const median = nums.length & 1 ?
        nums[halfLen] :
        Math.floor((nums[halfLen - 1] + nums[halfLen]) / 2);

    let res = 0;

    for (const num of nums) {
        res += Math.abs(num - median);
    }

    return res;
};
